mapper.select:
select

from bucket_info a
left join user_info b on a.user_id = b.user_id


    a.user_id = #{userId}


    a.user_id is null


    a.bucket_no = #{bucketNo}


    a.create_time >= #{startTime}


    a.create_time <= #{endTime}


order by a.create_time desc

select

    ,a.capacity_add as capacityDdd
from bucket_operate_log a
left join user_info b on a.user_id = b.user_id


    b.user_name = #{userName}


    a.bucket_no = like '%' || #{bucketNo} || '%'


    a.create_time >= #{startTime}


    a.create_time <= #{endTime}


order by a.create_time desc

select
, a.spec,a.status
from bucket_apply_log a
left join user_info b on a.user_id = b.user_id


    b.user_name = #{userName}


    a.bucket_no = #{bucketNo}


    a.type = #{type}


    a.create_time >= #{startTime}


    a.create_time <= #{endTime}


order by a.create_time desc

mapper.update:
update bucket_apply_log



      status = #{status},

    update_time = datetime('now')




    user_id = #{userId}


    and bucket_no = #{bucketNo}
